#pragma once
#include <stdexcept>

class IntStack {
public:
    explicit IntStack(int capacity = 5) : capacity_(capacity), top_(-1) {
        data_ = new int[capacity_];
    }

    ~IntStack() {
        delete[] data_;
    }

    void push(int value) {
        if (isFull()) {
            throw std::overflow_error("IntStack is full");
        }
        data_[++top_] = value;
    }

    int pop() {
        if (isEmpty()) {
            throw std::underflow_error("IntStack is empty");
        }
        return data_[top_--];
    }

    int peek() const {
        if (isEmpty()) {
            throw std::underflow_error("IntStack is empty");
        }
        return data_[top_];
    }

    bool isEmpty() const { return top_ == -1; }
    bool isFull() const { return top_ == capacity_ - 1; }
    int size() const { return top_ + 1; }

private:
    int* data_;
    int capacity_;
    int top_;
};
